// ===========================================================================
// 3. assertion helpers, guest argument buffers, table helpers
// ===========================================================================

static int g_assert_pass = 0;
static int g_assert_fail = 0;
static int g_case_fail = 0;

#define CHECK(cond)                                                              \
    do {                                                                         \
        if (cond) {                                                              \
            ++g_assert_pass;                                                     \
        } else {                                                                 \
            ++g_assert_fail;                                                     \
            ++g_case_fail;                                                       \
            std::printf("  FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);        \
        }                                                                        \
    } while (0)

#define CHECK_U32(expr, want)                                                    \
    do {                                                                         \
        const uint32_t _got = (uint32_t)(expr);                                  \
        const uint32_t _want = (uint32_t)(want);                                 \
        if (_got == _want) {                                                     \
            ++g_assert_pass;                                                     \
        } else {                                                                 \
            ++g_assert_fail;                                                     \
            ++g_case_fail;                                                       \
            std::printf("  FAIL %s:%d: %s = 0x%08X, want 0x%08X\n", __FILE__,    \
                        __LINE__, #expr, (unsigned)_got, (unsigned)_want);       \
        }                                                                        \
    } while (0)

#define CHECK_U64(expr, want)                                                    \
    do {                                                                         \
        const uint64_t _got = (uint64_t)(expr);                                  \
        const uint64_t _want = (uint64_t)(want);                                 \
        if (_got == _want) {                                                     \
            ++g_assert_pass;                                                     \
        } else {                                                                 \
            ++g_assert_fail;                                                     \
            ++g_case_fail;                                                       \
            std::printf("  FAIL %s:%d: %s = 0x%016llX, want 0x%016llX\n",        \
                        __FILE__, __LINE__, #expr, (unsigned long long)_got,     \
                        (unsigned long long)_want);                              \
        }                                                                        \
    } while (0)

struct Args {
    uint32_t regs[4];
    uint32_t stack[16];
};

static const gxm_abi_entry* entry_of(const char* name) {
    for (unsigned i = 0; i < GXM_ABI_ENTRY_COUNT; ++i) {
        const gxm_abi_entry& e = g_gxm_abi_table[i];
        if (e.name && std::strcmp(e.name, name) == 0) return &e;
    }
    return nullptr;
}

static uint32_t stub_of(const char* name) {
    const gxm_abi_entry* e = entry_of(name);
    if (!e) {
        std::printf("FATAL: stub_of(%s): entry not found\n", name);
        std::exit(98);
    }
    return e->stub;
}

static bool same_name(const gxm_abi_entry& e, const char* name) {
    return e.name && std::strcmp(e.name, name) == 0;
}

// ===========================================================================
// 4. test cases
// ===========================================================================

// ---- 4.1 table integrity ---------------------------------------------------
static void t_table_integrity() {
    CHECK_U32(g_gxm_abi_count, GXM_ABI_ENTRY_COUNT);
    CHECK_U32(GXM_ABI_ENTRY_COUNT, 100u);

    bool fields_ok = true;
    bool sorted_ok = true;
    bool stubs_unique = true;
    bool nids_unique = true;
    bool lookup_ok = true;
    unsigned n_typed = 0, n_stub = 0, n_real = 0;
    unsigned n_stack_decl = 0, n_stack_typed = 0;

    for (unsigned i = 0; i < GXM_ABI_ENTRY_COUNT; ++i) {
        const gxm_abi_entry& e = g_gxm_abi_table[i];
        if (!e.fn || !e.name || !e.name[0] || e.nid == 0u) fields_ok = false;
        if (e.kind > 2u) fields_ok = false;
        if (e.nargs > 20u) fields_ok = false;
        if (e.stub < 0x812B11C0u || e.stub > 0x812B17F0u) fields_ok = false;
        if (i > 0 && !(e.stub > g_gxm_abi_table[i - 1].stub)) sorted_ok = false;
        if (gxm_abi_lookup(e.stub) != &e) lookup_ok = false;

        if (e.nargs > 4u) {
            ++n_stack_decl;
            if (e.kind == 0u) ++n_stack_typed;
        }
        if (e.kind == 0u) ++n_typed;
        else if (e.kind == 1u) ++n_stub;
        else if (e.kind == 2u) ++n_real;
    }
    for (unsigned i = 0; i < GXM_ABI_ENTRY_COUNT && (stubs_unique || nids_unique); ++i) {
        for (unsigned j = i + 1; j < GXM_ABI_ENTRY_COUNT; ++j) {
            if (g_gxm_abi_table[i].stub == g_gxm_abi_table[j].stub) stubs_unique = false;
            if (g_gxm_abi_table[i].nid == g_gxm_abi_table[j].nid) nids_unique = false;
        }
    }

    CHECK(fields_ok);
    CHECK(sorted_ok);
    CHECK(stubs_unique);
    CHECK(nids_unique);
    CHECK(lookup_ok);
    CHECK_U32(n_typed, 25u);  // typed runtime calls
    CHECK_U32(n_stub, 74u);   // STUB_LOG-only placeholders
    CHECK_U32(n_real, 1u);    // placeholder with a real body (sceGxmTerminate)
    CHECK_U32(n_typed + n_stub + n_real, 100u);

    // Declared stack-argument census of the generated table (measured by this test).
    // 17 entries declare >4 guest arguments; only the 6 typed ones actually read
    // stack_args, the other 11 are STUB_LOG placeholders that drop their arguments
    // (one of them, sceGxmTransferCopy, declares 20 guest arguments).
    CHECK_U32(n_stack_decl, 17u);
    CHECK_U32(n_stack_typed, 6u);
    CHECK_U32(n_stack_decl - n_stack_typed, 11u);

    // Endpoints and the critical stub<->NID mapping from _gxm_table.csv.
    CHECK_U32(g_gxm_abi_table[0].stub, 0x812B11C0u);
    CHECK_U32(g_gxm_abi_table[0].nid, 0x008402C6u);
    CHECK(same_name(g_gxm_abi_table[0], "sceGxmMapFragmentUsseMemory"));
    CHECK_U32(g_gxm_abi_table[99].stub, 0x812B17F0u);
    CHECK_U32(g_gxm_abi_table[99].nid, 0xFE300E2Fu);
    CHECK(same_name(g_gxm_abi_table[99], "sceGxmEndScene"));

    struct Known {
        const char* name;
        uint32_t nid;
        uint32_t stub;
    };
    static const Known known[] = {
        {"sceGxmTextureInitLinear", 0x4811AECBu, 0x812B1340u},
        {"sceGxmTextureInitSwizzled", 0xD572D547u, 0x812B1680u},
        {"sceGxmTextureInitTiled", 0xE6F0DB27u, 0x812B16E0u},
        {"sceGxmDraw", 0xBC059AFCu, 0x812B15F0u},
        {"sceGxmBeginScene", 0x8734FF4Eu, 0x812B1470u},
        {"sceGxmSetViewport", 0x3EB3380Bu, 0x812B1300u},
        {"sceGxmMapMemory", 0xC61E34FCu, 0x812B1640u},
        {"sceGxmSyncObjectCreate", 0x6A6013E1u, 0x812B13D0u},
        {"sceGxmColorSurfaceInit", 0xED0F6E25u, 0x812B1730u},
    };
    for (unsigned i = 0; i < sizeof(known) / sizeof(known[0]); ++i) {
        const gxm_abi_entry* e = entry_of(known[i].name);
        CHECK(e != nullptr);
        if (e) {
            CHECK_U32(e->nid, known[i].nid);
            CHECK_U32(e->stub, known[i].stub);
        }
    }
}

// ---- 4.2 lookup / dispatch of unmapped stubs -------------------------------
static void t_lookup_unmapped() {
    reset_scenario();
    uint32_t regs[4] = {0x11111111u, 0x22222222u, 0x33333333u, 0x44444444u};
    uint32_t stack[4] = {0x55555555u, 0x66666666u, 0x77777777u, 0x88888888u};

    CHECK(gxm_abi_lookup(0x812B0000u) == nullptr);
    CHECK(gxm_abi_lookup(0x812B11C8u) == nullptr);  // midpoint between two stubs
    CHECK(gxm_abi_lookup(0x00000000u) == nullptr);
    CHECK(gxm_abi_lookup(0xDEADBEEFu) == nullptr);

    CHECK_U32(gxm_abi_dispatch(0x812B0000u, regs, stack), 0u);
    CHECK_U32(gxm_abi_dispatch(0x812B11C8u, regs, stack), 0u);
    CHECK_U32(gxm_abi_dispatch(0x00000000u, regs, stack), 0u);
    CHECK_U32(gxm_abi_dispatch(0xDEADBEEFu, regs, stack), 0u);
    CHECK_U32(gxm_abi_dispatch(0x812B0000u, nullptr, nullptr), 0u);
    CHECK_U32(g_rec_n, 0u);  // unmapped stub must not reach the backend
    CHECK_U32(g_xlate64_calls, 0u);
    CHECK_U32(g_xlate32_calls, 0u);
}

// ---- 4.3 sceGxmMapMemory: RAW base VA + return-code passthrough ------------
static void t_map_memory_raw() {
    static const uint32_t rets[] = {0u, 1u, 0xDEADBEEFu, 0xFFFFFFFEu, 0x80000000u};
    for (unsigned i = 0; i < sizeof(rets) / sizeof(rets[0]); ++i) {
        reset_scenario();
        set_ret_bits(rets[i]);
        Args a{};
        a.regs[0] = 0x81234567u;  // guest memory base: RAW, must not be translated
        a.regs[1] = 0x4000u;
        a.regs[2] = 0x3u;
        a.stack[0] = 0xAAAAAAAAu;  // junk: MapMemory has 3 args only

        const uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmMapMemory"), a.regs, a.stack);
        CHECK_U32(rv, rets[i]);
        CHECK_U32(g_rec_n, 1u);
        const RecCall* c = rec_find(REC_MAP_MEMORY);
        CHECK(c != nullptr);
        if (c) {
            CHECK_U64(c->a[0], 0x81234567u);  // exact RAW guest VA
            CHECK_U64(c->a[1], 0x4000u);
            CHECK_U64(c->a[2], 0x3u);
        }
        // RAW argument must bypass the translation hooks entirely.
        CHECK_U32(g_xlate64_calls, 0u);
        CHECK_U32(g_xlate32_calls, 0u);
    }
}

// ---- 4.4 texture init family: stack args + RAW data pointer ----------------
static void check_texture_init_case(const char* func_name, int rec_id, uint32_t fmt,
                                    uint32_t width, uint32_t height, uint32_t mip,
                                    uint32_t ret_bits) {
    reset_scenario();
    set_ret_bits(ret_bits);
    Args a{};
    a.regs[0] = GVA_TEX;         // SceGxmTexture *: translated
    a.regs[1] = GVA_RAW_DATA;    // const void * data: RAW guest VA, not translated
    a.regs[2] = fmt;             // r2
    a.regs[3] = width;           // r3
    a.stack[0] = height;         // 5th guest argument: stack_args[0]
    a.stack[1] = mip;            // 6th guest argument: stack_args[1]

    const uint32_t rv = gxm_abi_dispatch(stub_of(func_name), a.regs, a.stack);
    CHECK_U32(rv, ret_bits);
    CHECK_U32(g_rec_n, 1u);
    const RecCall* c = rec_find(rec_id);
    CHECK(c != nullptr);
    if (c) {
        CHECK_U64(c->a[0], host_addr(GVA_TEX));
        CHECK_U64(c->a[1], GVA_RAW_DATA);
        CHECK_U64(c->a[2], fmt);
        CHECK_U64(c->a[3], width);
        CHECK_U64(c->a[4], height);
        CHECK_U64(c->a[5], mip);
    }
    CHECK_U32(g_xlate64_calls, 1u);  // only the texture pointer is translated
    CHECK_U32(g_xlate32_calls, 0u);
}

static void t_texture_init_linear() {
    check_texture_init_case("sceGxmTextureInitLinear", REC_TEXTURE_INIT_LINEAR, 0x01020304u,
                            256u, 128u, 1u, 0u);
}

static void t_texture_init_swizzled() {
    check_texture_init_case("sceGxmTextureInitSwizzled", REC_TEXTURE_INIT_SWIZZLED, 0x05060708u,
                            512u, 256u, 4u, 0xFFFFFFFEu);
}

static void t_texture_init_tiled() {
    check_texture_init_case("sceGxmTextureInitTiled", REC_TEXTURE_INIT_TILED, 0x0A0B0C0Du,
                            1024u, 512u, 0u, 0x7FFFFFFFu);
}

// ---- 4.5 sceGxmDraw: 5th stack arg + count/indices swap --------------------
static void t_draw() {
    reset_scenario();
    set_ret_bits(7u);
    Args a{};
    a.regs[0] = GVA_CTX;
    a.regs[1] = 3u;         // SceGxmPrimitiveType
    a.regs[2] = 1u;         // SceGxmIndexFormat
    a.regs[3] = GVA_INDEX;  // const void * indexData
    a.stack[0] = 42u;       // 5th guest argument: unsigned int indexCount

    const uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmDraw"), a.regs, a.stack);
    CHECK_U32(rv, 7u);
    CHECK_U32(g_rec_n, 1u);
    const RecCall* c = rec_find(REC_DRAW);
    CHECK(c != nullptr);
    if (c) {
        // runtime order: (context, mode, indexType, count, indices)
        CHECK_U64(c->a[0], host_addr(GVA_CTX));
        CHECK_U64(c->a[1], 3u);
        CHECK_U64(c->a[2], 1u);
        CHECK_U64(c->a[3], 42u);
        CHECK_U64(c->a[4], host_addr(GVA_INDEX));
    }
    CHECK_U32(g_xlate64_calls, 2u);
    CHECK_U32(g_xlate32_calls, 0u);
    CHECK_U32(g_xlate64_last, GVA_INDEX);
}

// ---- 4.6 sceGxmSetViewport: 3 stack floats + x/y scale-offset reorder -----
static void t_set_viewport() {
    reset_scenario();
    const float x_off = 1.5f, x_scale = 2.5f, y_off = 3.5f;
    const float y_scale = 4.5f, z_off = 5.5f, z_scale = 6.5f;
    Args a{};
    a.regs[0] = GVA_CTX;
    a.regs[1] = f32_bits(x_off);
    a.regs[2] = f32_bits(x_scale);
    a.regs[3] = f32_bits(y_off);
    a.stack[0] = f32_bits(y_scale);
    a.stack[1] = f32_bits(z_off);
    a.stack[2] = f32_bits(z_scale);

    const uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmSetViewport"), a.regs, a.stack);
    CHECK_U32(rv, 0u);
    CHECK_U32(g_rec_n, 1u);
    const RecCall* c = rec_find(REC_SET_VIEWPORT);
    CHECK(c != nullptr);
    if (c) {
        // guest:   (ctx, xOffset, xScale, yOffset, yScale, zOffset, zScale)
        // runtime: (ctx, xOffset, yOffset, xScale, yScale, zScale, zOffset)
        CHECK_U64(c->a[0], host_addr(GVA_CTX));
        CHECK_U64(c->a[1], f32_bits(x_off));
        CHECK_U64(c->a[2], f32_bits(y_off));    // r3 -> 3rd backend arg
        CHECK_U64(c->a[3], f32_bits(x_scale));  // r2 -> 4th backend arg
        CHECK_U64(c->a[4], f32_bits(y_scale));  // stack_args[0]
        CHECK_U64(c->a[5], f32_bits(z_scale));  // stack_args[2]
        CHECK_U64(c->a[6], f32_bits(z_off));    // stack_args[1]
    }
    CHECK_U32(g_xlate64_calls, 1u);
    CHECK_U32(g_xlate32_calls, 0u);
}

// ---- 4.7 sceGxmBeginScene: 8->7 manual map, 4 stack args, validRegion drop -
static void t_begin_scene() {
    reset_scenario();
    set_ret_bits(0xFFFFFFFFu);  // negative error passthrough
    Args a{};
    a.regs[0] = GVA_CTX;
    a.regs[1] = 0x11u;         // flags
    a.regs[2] = GVA_RT;
    a.regs[3] = GVA_VREGION;   // validRegion: dropped by the manual map
    a.stack[0] = GVA_VSYNC;
    a.stack[1] = GVA_FSYNC;
    a.stack[2] = GVA_COLOR;
    a.stack[3] = GVA_DEPTH;

    const uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmBeginScene"), a.regs, a.stack);
    CHECK_U32(rv, 0xFFFFFFFFu);
    CHECK_U32(g_rec_n, 1u);
    const RecCall* c = rec_find(REC_BEGIN_SCENE);
    CHECK(c != nullptr);
    if (c) {
        // runtime order: (ctx, flags, rt, color, depth, vertexSync, fragmentSync)
        CHECK_U64(c->a[0], host_addr(GVA_CTX));
        CHECK_U64(c->a[1], 0x11u);
        CHECK_U64(c->a[2], host_addr(GVA_RT));
        CHECK_U64(c->a[3], host_addr(GVA_COLOR));
        CHECK_U64(c->a[4], host_addr(GVA_DEPTH));
        CHECK_U64(c->a[5], host_addr(GVA_VSYNC));
        CHECK_U64(c->a[6], host_addr(GVA_FSYNC));
        bool vregion_leaked = false;
        for (int k = 0; k < 7; ++k) {
            if (c->a[k] == host_addr(GVA_VREGION)) vregion_leaked = true;
        }
        CHECK(!vregion_leaked);  // validRegion must not be passed to the backend
    }
    // ctx + rt + color + depth + vertexSync + fragmentSync are translated; the dropped
    // validRegion (r3) is not.
    CHECK_U32(g_xlate64_calls, 6u);
    CHECK_U32(g_xlate32_calls, 0u);
    CHECK_U32(g_xlate64_last, GVA_FSYNC);
}

// ---- 4.8 sceGxmSyncObjectCreate: out-handle round-trip --------------------
static void t_sync_object_create() {
    // success path: backend returns a host handle -> guest slot gets untranslated handle
    reset_scenario();
    *guest_slot(GVA_OUT_SLOT) = 0xCCCCCCCCu;
    g_out_handle = handle_host(1);
    set_ret_bits(0u);
    Args a{};
    a.regs[0] = GVA_OUT_SLOT;
    uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmSyncObjectCreate"), a.regs, a.stack);
    CHECK_U32(rv, 0u);
    CHECK_U32(g_rec_n, 1u);
    const RecCall* c = rec_find(REC_SYNC_OBJECT_CREATE);
    CHECK(c != nullptr);
    if (c) CHECK(c->a[0] != 0u);  // backend receives a host-side out pointer
    CHECK_U32(*guest_slot(GVA_OUT_SLOT), guest_handle_for(1));
    CHECK_U32(g_xlate64_calls, 1u);
    CHECK_U32(g_untranslate_calls, 1u);
    CHECK_U64(g_untranslate_last, (uint64_t)(uintptr_t)handle_host(1));

    // failure path: no host handle -> guest slot untouched, rv still passed through
    reset_scenario();
    *guest_slot(GVA_OUT_SLOT) = 0xCCCCCCCCu;
    g_out_handle = nullptr;
    set_ret_bits(0xFFFFFFFEu);
    rv = gxm_abi_dispatch(stub_of("sceGxmSyncObjectCreate"), a.regs, a.stack);
    CHECK_U32(rv, 0xFFFFFFFEu);
    CHECK_U32(g_rec_n, 1u);
    CHECK_U32(*guest_slot(GVA_OUT_SLOT), 0xCCCCCCCCu);
    CHECK_U32(g_untranslate_calls, 0u);
}

// ---- 4.9 ShaderPatcherCreate / CreateRenderTarget / CreateContext ---------
static void t_create_handle_functions() {
    struct OutCase {
        const char* func;
        int rec_id;
        int handle_idx;
    };
    static const OutCase cases[] = {
        {"sceGxmShaderPatcherCreate", REC_SHADER_PATCHER_CREATE, 1},
        {"sceGxmCreateRenderTarget", REC_CREATE_RENDER_TARGET, 2},
        {"sceGxmCreateContext", REC_CREATE_CONTEXT, 3},
    };
    for (unsigned i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        reset_scenario();
        *guest_slot(GVA_OUT_SLOT) = 0xCCCCCCCCu;
        g_out_handle = handle_host(cases[i].handle_idx);
        set_ret_bits(0u);
        Args a{};
        a.regs[0] = GVA_PARAMS;
        a.regs[1] = GVA_OUT_SLOT;
        const uint32_t rv = gxm_abi_dispatch(stub_of(cases[i].func), a.regs, a.stack);
        CHECK_U32(rv, 0u);
        CHECK_U32(g_rec_n, 1u);
        const RecCall* c = rec_find(cases[i].rec_id);
        CHECK(c != nullptr);
        if (c) CHECK_U64(c->a[0], host_addr(GVA_PARAMS));
        CHECK_U32(*guest_slot(GVA_OUT_SLOT), guest_handle_for(cases[i].handle_idx));
        CHECK_U32(g_xlate64_calls, 2u);  // params + out slot
        CHECK_U32(g_untranslate_calls, 1u);
    }

    // error path for one of them: no host handle -> rv passthrough, slot untouched
    reset_scenario();
    *guest_slot(GVA_OUT_SLOT) = 0xCCCCCCCCu;
    g_out_handle = nullptr;
    set_ret_bits(0xFFFFFFFDu);
    Args a{};
    a.regs[0] = GVA_PARAMS;
    a.regs[1] = GVA_OUT_SLOT;
    const uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmCreateRenderTarget"), a.regs, a.stack);
    CHECK_U32(rv, 0xFFFFFFFDu);
    CHECK_U32(*guest_slot(GVA_OUT_SLOT), 0xCCCCCCCCu);
    CHECK_U32(g_untranslate_calls, 0u);
}

// ---- 4.10 Usse memory mapping: RAW base + translated offset + pointer rv --
static void check_map_usse_case(const char* func_name, int rec_id, uint32_t raw_base,
                                uint32_t size, int handle_idx) {
    reset_scenario();
    g_ret_ptr = handle_host(handle_idx);
    Args a{};
    a.regs[0] = raw_base;    // RAW guest VA: not translated
    a.regs[1] = size;
    a.regs[2] = GVA_OFFSET;  // SceUInt32 * offset: translated
    const uint32_t rv = gxm_abi_dispatch(stub_of(func_name), a.regs, a.stack);
    // host pointer return value must be converted back to a guest handle
    CHECK_U32(rv, guest_handle_for(handle_idx));
    CHECK_U32(g_rec_n, 1u);
    const RecCall* c = rec_find(rec_id);
    CHECK(c != nullptr);
    if (c) {
        CHECK_U64(c->a[0], raw_base);
        CHECK_U64(c->a[1], size);
        CHECK_U64(c->a[2], host_addr(GVA_OFFSET));
    }
    CHECK_U32(g_xlate64_calls, 1u);
    CHECK_U32(g_xlate32_calls, 0u);
    CHECK_U32(g_untranslate_calls, 1u);
    CHECK_U64(g_untranslate_last, (uint64_t)(uintptr_t)handle_host(handle_idx));
}

static void t_map_usse_memory() {
    check_map_usse_case("sceGxmMapFragmentUsseMemory", REC_MAP_FRAGMENT_USSE, 0x91000000u,
                        0x2000u, 0);
    check_map_usse_case("sceGxmMapVertexUsseMemory", REC_MAP_VERTEX_USSE, 0x92000000u, 0x3000u,
                        2);

    // untranslatable host pointer -> guest receives NULL (never a raw host pointer)
    reset_scenario();
    g_ret_ptr = unknown_host_ptr();
    Args a{};
    a.regs[0] = 0x91000000u;
    a.regs[1] = 0x1000u;
    a.regs[2] = GVA_OFFSET;
    const uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmMapFragmentUsseMemory"), a.regs, a.stack);
    CHECK_U32(rv, 0u);
    CHECK_U32(g_untranslate_calls, 1u);

    // NULL backend return -> NULL guest return, no untranslate call needed
    reset_scenario();
    g_ret_ptr = nullptr;
    a.regs[0] = 0x91000000u;
    a.regs[1] = 0x1000u;
    a.regs[2] = GVA_OFFSET;
    const uint32_t rv2 = gxm_abi_dispatch(stub_of("sceGxmMapFragmentUsseMemory"), a.regs, a.stack);
    CHECK_U32(rv2, 0u);
    CHECK_U32(g_untranslate_calls, 0u);
}

// ---- 4.11 sceGxmTerminate: kind-2 placeholder with a real body ------------
static void t_terminate_realbody() {
    const gxm_abi_entry* e = entry_of("sceGxmTerminate");
    CHECK(e != nullptr);
    if (e) {
        CHECK_U32(e->kind, 2u);  // only entry with a real backend body
        CHECK_U32(e->nargs, 0u);
    }
    reset_scenario();
    set_ret_bits(0x12345678u);
    Args a{};
    const uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmTerminate"), a.regs, a.stack);
    CHECK_U32(rv, 0x12345678u);
    CHECK_U32(g_rec_n, 1u);
    CHECK(rec_find(REC_TERMINATE) != nullptr);
    CHECK_U32(g_xlate64_calls, 0u);
    CHECK_U32(g_xlate32_calls, 0u);
}

// ---- 4.12 all STUB_LOG placeholders (kind 1) return 0, drop their args ----
static void t_stub_placeholders() {
    Args a{};
    for (int i = 0; i < 4; ++i) a.regs[i] = 0xA5A5A5A5u;
    for (int i = 0; i < 16; ++i) a.stack[i] = 0x5A5A5A5Au;

    unsigned n_checked = 0;
    for (unsigned i = 0; i < GXM_ABI_ENTRY_COUNT; ++i) {
        const gxm_abi_entry& e = g_gxm_abi_table[i];
        if (e.kind != 1u) continue;
        ++n_checked;
        reset_scenario();
        const uint32_t rv = gxm_abi_dispatch(e.stub, a.regs, a.stack);
        if (rv != 0u) std::printf("  [stub returned non-zero: %s]\n", e.name);
        CHECK_U32(rv, 0u);
        if (g_rec_n != 0) std::printf("  [stub reached backend: %s]\n", e.name);
        CHECK_U32(g_rec_n, 0u);
        CHECK_U32(g_xlate64_calls, 0u);  // arguments are intentionally dropped
        CHECK_U32(g_xlate32_calls, 0u);
    }
    CHECK_U32(n_checked, 74u);
}

// ---- 4.13 every one of the 100 table entries dispatches without crashing --
static void t_full_table_smoke() {
    Args a{};  // all-zero guest state: every pointer argument is NULL
    unsigned n_typed = 0, n_stub = 0, n_real = 0;
    for (unsigned i = 0; i < GXM_ABI_ENTRY_COUNT; ++i) {
        const gxm_abi_entry& e = g_gxm_abi_table[i];
        reset_scenario();
        set_ret_bits(0x5A5A5A5Au);
        const uint32_t rv = gxm_abi_dispatch(e.stub, a.regs, a.stack);
        if (e.kind == 0u) {
            ++n_typed;
            const bool ptr_return = same_name(e, "sceGxmMapFragmentUsseMemory") ||
                                    same_name(e, "sceGxmMapVertexUsseMemory");
            const uint32_t want = ptr_return ? 0u : 0x5A5A5A5Au;
            if (rv != want) std::printf("  [typed wrapper: %s]\n", e.name);
            CHECK_U32(rv, want);
            CHECK_U32(g_rec_n, 1u);  // exactly one backend call per typed wrapper
        } else if (e.kind == 1u) {
            ++n_stub;
            if (rv != 0u) std::printf("  [stub wrapper: %s]\n", e.name);
            CHECK_U32(rv, 0u);
            CHECK_U32(g_rec_n, 0u);
        } else {
            ++n_real;
            if (rv != 0x5A5A5A5Au) std::printf("  [real-body wrapper: %s]\n", e.name);
            CHECK_U32(rv, 0x5A5A5A5Au);
            CHECK_U32(g_rec_n, 1u);
        }
    }
    CHECK_U32(n_typed, 25u);
    CHECK_U32(n_stub, 74u);
    CHECK_U32(n_real, 1u);
}

// ---- 4.14 pointer-argument decoding for the remaining typed wrappers ------
struct CallArg {
    bool is_ptr;
    uint32_t value;
};

struct PtrCase {
    const char* func;
    int rec_id;
    int nargs;
    CallArg args[3];
};

static void run_ptr_case(const PtrCase& pc) {
    reset_scenario();
    set_ret_bits(0xFFFFFFF9u);
    Args a{};
    for (int i = 0; i < pc.nargs && i < 4; ++i) a.regs[i] = pc.args[i].value;
    const uint32_t rv = gxm_abi_dispatch(stub_of(pc.func), a.regs, a.stack);
    CHECK_U32(rv, 0xFFFFFFF9u);
    CHECK_U32(g_rec_n, 1u);
    const RecCall* c = rec_find(pc.rec_id);
    CHECK(c != nullptr);
    if (c) {
        for (int i = 0; i < pc.nargs; ++i) {
            const uint64_t want =
                pc.args[i].is_ptr ? host_addr(pc.args[i].value) : (uint64_t)pc.args[i].value;
            CHECK_U64(c->a[i], want);
        }
    }
    int nptr = 0;
    for (int i = 0; i < pc.nargs; ++i) {
        if (pc.args[i].is_ptr) ++nptr;
    }
    CHECK_U32(g_xlate64_calls, (uint32_t)nptr);
    CHECK_U32(g_xlate32_calls, 0u);
}

static void t_pointer_functions() {
    PtrCase cases[] = {
        // func, rec id, nargs, {is_ptr, value}
        {"sceGxmSetVertexProgram", REC_SET_VERTEX_PROGRAM, 2, {{true, GVA_CTX}, {true, GVA_TEX}, {false, 0u}}},
        {"sceGxmSetFragmentProgram", REC_SET_FRAGMENT_PROGRAM, 2, {{true, GVA_CTX}, {true, GVA_TEX}, {false, 0u}}},
        {"sceGxmSetVertexStream", REC_SET_VERTEX_STREAM, 3, {{true, GVA_CTX}, {false, 2u}, {true, GVA_INDEX}}},
        {"sceGxmSetFragmentTexture", REC_SET_FRAGMENT_TEXTURE, 3, {{true, GVA_CTX}, {false, 3u}, {true, GVA_TEX}}},
        {"sceGxmSetVertexTexture", REC_SET_VERTEX_TEXTURE, 3, {{true, GVA_CTX}, {false, 4u}, {true, GVA_TEX}}},
        {"sceGxmDisplayQueueAddEntry", REC_DISPLAY_QUEUE_ADD_ENTRY, 3, {{true, GVA_VSYNC}, {true, GVA_FSYNC}, {true, GVA_COLOR}}},
        {"sceGxmDestroyRenderTarget", REC_DESTROY_RENDER_TARGET, 1, {{true, GVA_RT}, {false, 0u}, {false, 0u}}},
        {"sceGxmSyncObjectDestroy", REC_SYNC_OBJECT_DESTROY, 1, {{true, GVA_VSYNC}, {false, 0u}, {false, 0u}}},
        {"sceGxmShaderPatcherDestroy", REC_SHADER_PATCHER_DESTROY, 1, {{true, GVA_PARAMS}, {false, 0u}, {false, 0u}}},
        {"sceGxmDestroyContext", REC_DESTROY_CONTEXT, 1, {{true, GVA_CTX}, {false, 0u}, {false, 0u}}},
        {"sceGxmEndScene", REC_END_SCENE, 3, {{true, GVA_CTX}, {true, GVA_VSYNC}, {true, GVA_FSYNC}}},
        {"sceGxmInitialize", REC_INITIALIZE, 1, {{true, GVA_PARAMS}, {false, 0u}, {false, 0u}}},
    };
    for (unsigned i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        if (!entry_of(cases[i].func)) std::printf("  [missing entry: %s]\n", cases[i].func);
        run_ptr_case(cases[i]);
    }
}

// ---- 4.15 NULL guest pointers are never translated / never dereferenced ---
static void t_null_inputs() {
    // typed wrapper with all-zero pointer args
    reset_scenario();
    set_ret_bits(0x77u);
    Args a{};
    uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmSetFragmentTexture"), a.regs, a.stack);
    CHECK_U32(rv, 0x77u);
    const RecCall* c = rec_find(REC_SET_FRAGMENT_TEXTURE);
    CHECK(c != nullptr);
    if (c) {
        CHECK_U64(c->a[0], 0u);
        CHECK_U64(c->a[1], 0u);
        CHECK_U64(c->a[2], 0u);
    }
    CHECK_U32(g_xlate64_calls, 0u);
    CHECK_U32(g_xlate32_calls, 0u);

    // NULL regs / NULL stack_args: guards must yield zeroed arguments, no crash
    reset_scenario();
    set_ret_bits(0x123u);
    rv = gxm_abi_dispatch(stub_of("sceGxmDraw"), nullptr, nullptr);
    CHECK_U32(rv, 0x123u);
    c = rec_find(REC_DRAW);
    CHECK(c != nullptr);
    if (c) {
        CHECK_U64(c->a[0], 0u);
        CHECK_U64(c->a[3], 0u);  // stack arg count reads 0 without a stack pointer
        CHECK_U64(c->a[4], 0u);
    }
    CHECK_U32(g_xlate64_calls, 0u);

    reset_scenario();
    set_ret_bits(0u);
    rv = gxm_abi_dispatch(stub_of("sceGxmSetViewport"), nullptr, nullptr);
    CHECK_U32(rv, 0u);
    c = rec_find(REC_SET_VIEWPORT);
    CHECK(c != nullptr);
    if (c) {
        for (int k = 0; k < 7; ++k) CHECK_U64(c->a[k], 0u);
    }
    CHECK_U32(g_xlate64_calls, 0u);

    reset_scenario();
    set_ret_bits(0xFFFFFFF0u);
    rv = gxm_abi_dispatch(stub_of("sceGxmBeginScene"), nullptr, nullptr);
    CHECK_U32(rv, 0xFFFFFFF0u);
    c = rec_find(REC_BEGIN_SCENE);
    CHECK(c != nullptr);
    if (c) {
        for (int k = 0; k < 7; ++k) CHECK_U64(c->a[k], 0u);
    }
}

// ---- 4.16 64-bit preferred hook + 32-bit fallback hook --------------------
static void t_xlate_fallback() {
    // normal arena VA: translate64 succeeds, the 32-bit hook is never called
    reset_scenario();
    set_ret_bits(0x42u);
    Args a{};
    a.regs[0] = GVA_TEX;
    a.regs[1] = GVA_CTX;
    uint32_t rv = gxm_abi_dispatch(stub_of("sceGxmSetVertexProgram"), a.regs, a.stack);
    CHECK_U32(rv, 0x42u);
    const RecCall* c = rec_find(REC_SET_VERTEX_PROGRAM);
    CHECK(c != nullptr);
    if (c) {
        CHECK_U64(c->a[0], host_addr(GVA_TEX));
        CHECK_U64(c->a[1], host_addr(GVA_CTX));
    }
    CHECK_U32(g_xlate64_calls, 2u);
    CHECK_U32(g_xlate32_calls, 0u);  // preferred hook won

    // translate64 misses, translate (32-bit) claims the VA: fallback path is used
    reset_scenario();
    set_ret_bits(0x43u);
    a.regs[0] = GVA_FALLBACK;
    a.regs[1] = GVA_TEX;
    rv = gxm_abi_dispatch(stub_of("sceGxmSetVertexProgram"), a.regs, a.stack);
    CHECK_U32(rv, 0x43u);
    c = rec_find(REC_SET_VERTEX_PROGRAM);
    CHECK(c != nullptr);
    if (c) {
        CHECK_U64(c->a[0], 0xCAFEBABEu);  // pointer produced by the 32-bit hook
        CHECK_U64(c->a[1], host_addr(GVA_TEX));
    }
    CHECK_U32(g_xlate64_calls, 2u);
    CHECK_U32(g_xlate32_calls, 1u);
    CHECK_U32(g_xlate32_last, GVA_FALLBACK);

    // both hooks miss -> NULL pointer passed to the backend (safe no-op path)
    reset_scenario();
    set_ret_bits(0x44u);
    a.regs[0] = GVA_UNMAPPED;
    a.regs[1] = 0u;  // NULL is not translated at all
    rv = gxm_abi_dispatch(stub_of("sceGxmSetVertexProgram"), a.regs, a.stack);
    CHECK_U32(rv, 0x44u);
    c = rec_find(REC_SET_VERTEX_PROGRAM);
    CHECK(c != nullptr);
    if (c) {
        CHECK_U64(c->a[0], 0u);
        CHECK_U64(c->a[1], 0u);
    }
    CHECK_U32(g_xlate64_calls, 1u);
    CHECK_U32(g_xlate32_calls, 1u);
}

// ---- 4.17 dispatch() == table entry fn() for representative stubs ---------
static void t_dispatch_vs_direct() {
    struct EquivCase {
        const char* func;
        uint32_t regs[4];
        uint32_t stack[4];
    };
    static const EquivCase cases[] = {
        {"sceGxmDraw", {GVA_CTX, 4u, 0u, GVA_INDEX}, {9u, 0u, 0u, 0u}},
        {"sceGxmSetViewport", {GVA_CTX, 0x3F800000u, 0x40000000u, 0x40400000u},
         {0x40800000u, 0x40A00000u, 0x40C00000u, 0u}},
        {"sceGxmTextureInitLinear", {GVA_TEX, GVA_RAW_DATA, 2u, 64u}, {32u, 1u, 0u, 0u}},
        {"sceGxmMapMemory", {0x81234567u, 0x1000u, 1u}, {0u, 0u, 0u, 0u}},
        {"sceGxmSyncObjectCreate", {GVA_OUT_SLOT, 0u, 0u, 0u}, {0u, 0u, 0u, 0u}},
        {"sceGxmTerminate", {0u, 0u, 0u, 0u}, {0u, 0u, 0u, 0u}},
    };
    for (unsigned i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        const gxm_abi_entry* e = entry_of(cases[i].func);
        CHECK(e != nullptr);
        if (!e) continue;
        reset_scenario();
        set_ret_bits(0x0BADF00Du);
        const uint32_t via_dispatch = gxm_abi_dispatch(e->stub, (uint32_t*)cases[i].regs,
                                                        (uint32_t*)cases[i].stack);
        const int n_dispatch = g_rec_n;
        uintptr_t first_a0 = 0u;
        if (g_rec_n > 0) first_a0 = g_rec[0].a[0];
        reset_scenario();
        set_ret_bits(0x0BADF00Du);
        const uint32_t via_entry = e->fn((uint32_t*)cases[i].regs, (uint32_t*)cases[i].stack);
        const int n_entry = g_rec_n;
        uintptr_t first_a0_direct = 0u;
        if (g_rec_n > 0) first_a0_direct = g_rec[0].a[0];
        CHECK_U32(via_dispatch, via_entry);
        CHECK_U32((uint32_t)n_dispatch, (uint32_t)n_entry);
        CHECK_U64(first_a0, first_a0_direct);
    }
}

// ===========================================================================
// 5. runner
// ===========================================================================

struct TestCase {
    const char* name;
    void (*fn)();
};

int main() {
    static const TestCase cases[] = {
        {"table_integrity", t_table_integrity},
        {"lookup_unmapped", t_lookup_unmapped},
        {"map_memory_raw", t_map_memory_raw},
        {"texture_init_linear", t_texture_init_linear},
        {"texture_init_swizzled", t_texture_init_swizzled},
        {"texture_init_tiled", t_texture_init_tiled},
        {"draw", t_draw},
        {"set_viewport", t_set_viewport},
        {"begin_scene", t_begin_scene},
        {"sync_object_create", t_sync_object_create},
        {"create_handle_functions", t_create_handle_functions},
        {"map_usse_memory", t_map_usse_memory},
        {"terminate_realbody", t_terminate_realbody},
        {"stub_placeholders", t_stub_placeholders},
        {"full_table_smoke", t_full_table_smoke},
        {"pointer_functions", t_pointer_functions},
        {"null_inputs", t_null_inputs},
        {"xlate_fallback", t_xlate_fallback},
        {"dispatch_vs_direct", t_dispatch_vs_direct},
    };
    const unsigned n_cases = (unsigned)(sizeof(cases) / sizeof(cases[0]));

    std::printf("=== GXM ABI layer integration test ===\n");
    std::printf("layer: gxm_abi.cpp (generated)  entries: %u\n", (unsigned)GXM_ABI_ENTRY_COUNT);
    std::printf("backend: %d recording test doubles (no Vulkan device, no runtime .o)\n", 26);
    std::printf("hooks: translate64/translate/untranslate strong overrides\n\n");

    unsigned n_passed = 0;
    for (unsigned i = 0; i < n_cases; ++i) {
        g_case_fail = 0;
        const int pass_before = g_assert_pass;
        cases[i].fn();
        const int assertions = g_assert_pass - pass_before + g_case_fail;
        if (g_case_fail == 0) {
            ++n_passed;
            std::printf("[PASS] %-24s (%d assertions)\n", cases[i].name, assertions);
        } else {
            std::printf("[FAIL] %-24s (%d of %d assertions failed)\n", cases[i].name, g_case_fail,
                        assertions);
        }
    }

    std::printf("\n----------------------------------------\n");
    std::printf("cases:      %u run, %u passed, %u failed\n", n_cases, n_passed,
                n_cases - n_passed);
    std::printf("assertions: %d passed, %d failed\n", g_assert_pass, g_assert_fail);
    if (g_assert_fail == 0 && n_passed == n_cases) {
        std::printf("RESULT: PASS (GXM_ABI_TEST_PASS)\n");
        std::printf("GXM_ABI_TEST_PASS\n");
        return 0;
    }
    std::printf("RESULT: FAIL (GXM_ABI_TEST_FAIL)\n");
    std::printf("GXM_ABI_TEST_FAIL\n");
    return 1;
}
